package com.skillsphere.dto;

import java.util.List;

/**
 * @param source "gemini" when generated by Gemini, "rules" when the built-in fallback was used
 * @param notice optional message explaining why the fallback was used
 */
public record RecommendationResponse(
        String summary,
        List<Course> recommendations,
        String source,
        String notice
) {
    public record Course(
            String title,
            String skill,
            String level,
            String duration,
            String priority,
            String provider,
            String reason,
            List<String> topics,
            String searchQuery
    ) {}
}
